import { Table, TableNameColumn, FieldNameColumn, StringColumn, TranslatedTextColumn, GuidColumn } from '../../db'

export const sys_ui_style = Table({
    name: 'sys_ui_style',
    extends: 'sys_metadata',
    label: 'Style',
    schema: {
        name: TableNameColumn({
            label: 'Table',
            maxLength: 80,
        }),
        element: FieldNameColumn({
            dependent: 'name',
            label: 'Field name',
            maxLength: 80,
        }),
        value: StringColumn({
            label: 'Value',
            maxLength: 250,
        }),
        style: StringColumn({
            label: 'Style',
            maxLength: 1000,
        }),
        themed_style: StringColumn({
            label: 'Themed style',
            maxLength: 1000,
        }),
        alt: TranslatedTextColumn({
            label: 'Alternative text',
            maxLength: 100,
        }),
        sys_id: GuidColumn({
            label: 'Sys ID',
            primary: true,
        }),
    },
})
